"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[794085],{468916:e=>{e.exports=JSON.parse('{"label":"AI","permalink":"/tags/ai","allTagsPath":"/tags","count":2,"items":[{"id":"Cloud_Chain/Cloud/SenseCraft_Data/SenseCraft_Data_Platform/how_to_use_sensecap_data_platform_ai_advisor_on_the_web_and_sensecraft_app","title":"How to Use SenseCraft Data Platform AI Advisor on the web and SenseCraft APP","description":"Learn how to deploy the AI Advisor on SenseCraft Data Platform and App for advanced sensor data analysis. Automate monitoring, optimize operations, and unlock actionable insights with AI-powered solutions.","permalink":"/cloud/sensecraft-data/sensecraft-data-platform/how_to_use_sensecap_data_platform_ai_advisor_on_the_web_and_sensecraft_app"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Super/reComputer_Super_vs_Classic_Next-Gen_AI_Performance_in_Edge_Inferencing","title":"reComputer Super vs Classic Next-Gen AI Performance in Edge Inferencing","description":"This article highlights the superior AI performance of the reComputer Super compared to the reComputer Classic, demonstrating up to a 1.7x boost in AI compute power with the NVIDIA Jetson Orin NX 16GB. Through practical benchmarks in AI text generation using the DeepSeek-R1:7B model with Ollama, and AI video processing using the YOLOv11 object detection model, the results show that the reComputer Super delivers significantly faster inference speeds and higher GPU frequencies. Notably, it processes approximately 2.37 times more images per second than the Classic. The article also explains the importance of evaluating performance based on terminal-reported FPS rather than on-screen FPS, which can be limited by display and system factors.","permalink":"/recomputer_jetson_super_performance"}]}')}}]);